use lzma_turbo::{BLOCK_SIZE_AUTO, Error, Lzma2Encoder, LzmaEncProps, SeqInStream, SeqOutStream};
use std::{fs::File, io::{Read, Write}, time::Instant};
#[repr(C)]
#[derive(Default, Clone, Copy)]
struct TimeVal { sec: i64, usec: i64 }
#[repr(C)]
#[derive(Default, Clone, Copy)]
struct Usage { user: TimeVal, system: TimeVal, rest: [i64; 14] }
unsafe extern "C" { fn getrusage(who: i32, usage: *mut Usage) -> i32; }
struct Stamp { time: Instant, usage: Usage }
fn stamp() -> Stamp {
    let mut usage = Usage::default();
    // SAFETY: on Linux x86-64, Usage matches struct rusage, and the mutable
    // pointer covers its complete writable extent for this synchronous call.
    assert_eq!(unsafe { getrusage(0, &mut usage) }, 0);
    Stamp { time: Instant::now(), usage }
}
fn seconds(v: TimeVal) -> f64 { v.sec as f64 + v.usec as f64 / 1e6 }
fn phase(name: &str, before: &mut Stamp, rows: &mut Vec<String>) {
    let next = stamp();
    rows.push(format!("{{\"phase\":\"{}\",\"wall\":{:.9},\"user\":{:.6},\"system\":{:.6},\"minor_faults\":{},\"rss_kib\":{}}}", name, next.time.duration_since(before.time).as_secs_f64(), seconds(next.usage.user)-seconds(before.usage.user), seconds(next.usage.system)-seconds(before.usage.system), next.usage.rest[4]-before.usage.rest[4], next.usage.rest[0]));
    *before = next;
}
struct Input(File);
impl SeqInStream for Input { fn read(&mut self, b: &mut [u8]) -> Result<usize, Error> { self.0.read(b).map_err(|_| Error::Read) } }
struct Output { file: File, bytes: u64 }
impl SeqOutStream for Output { fn write(&mut self, b: &[u8]) -> Result<(), Error> { self.file.write_all(b).map_err(|_| Error::Write)?; self.bytes += b.len() as u64; Ok(()) } }
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let threads: u32 = args[2].parse().unwrap();
    let mut rows = Vec::new(); let mut previous = stamp();
    if args[1] == "stream" {
        let source = File::open(&args[3]).unwrap(); let len = source.metadata().unwrap().len();
        let mut input = Input(source); let mut output = Output { file: File::create("/dev/null").unwrap(), bytes: 0 };
        phase("input_open", &mut previous, &mut rows);
        let props = LzmaEncProps::new().with_level(5).with_num_threads(threads.min(2));
        let mut enc = Lzma2Encoder::new(&props).unwrap(); enc.set_total_threads(threads as usize); enc.set_block_size(BLOCK_SIZE_AUTO); enc.set_data_size(len); enc.set_data_limit(len);
        phase("setup", &mut previous, &mut rows);
        enc.encode_mt(&mut input, &mut output).unwrap(); let size = output.bytes;
        phase("encode", &mut previous, &mut rows);
        drop(enc); phase("encoder_drop", &mut previous, &mut rows);
        drop(output); drop(input); phase("io_drop", &mut previous, &mut rows);
        println!("{{\"bytes\":{},\"phases\":[{}]}}", size, rows.join(","));
    } else {
        let input = std::fs::read(&args[3]).unwrap(); phase("input_read", &mut previous, &mut rows);
        if args[1] == "read" {
            std::hint::black_box(&input); drop(input); phase("input_drop", &mut previous, &mut rows);
            println!("{{\"phases\":[{}]}}", rows.join(",")); return;
        }
        let props = LzmaEncProps::new().with_level(5).with_num_threads(threads.min(2));
        let mut enc = Lzma2Encoder::new(&props).unwrap(); enc.set_total_threads(threads as usize); enc.set_block_size(BLOCK_SIZE_AUTO);
        phase("setup", &mut previous, &mut rows);
        let output = enc.encode_to_vec(&input).unwrap(); let size = output.len();
        phase("encode", &mut previous, &mut rows);
        drop(enc); phase("encoder_drop", &mut previous, &mut rows);
        drop(output); phase("output_drop", &mut previous, &mut rows);
        drop(input); phase("input_drop", &mut previous, &mut rows);
        println!("{{\"bytes\":{},\"phases\":[{}]}}", size, rows.join(","));
    }
}

